using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval — returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// 2) Probe without throwing — TryGetTypeInfo returns false if unavailable
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
    Console.WriteLine($"TryGetTypeInfo succeeded for Person (kind: {info!.Kind})");

// Probe for a type whose metadata may NOT be resolvable
// (use a resolver that resolves nothing)
var restrictedOptions = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine() // empty — resolves nothing
};

if (!restrictedOptions.TryGetTypeInfo(typeof(Person), out _))
    Console.WriteLine("TryGetTypeInfo correctly returned false — no metadata available");

record Person(string Name, int Age);

